(function(){"use strict";document.addEventListener("click",e=>{const t=e.target.closest?.("a.stets-youtube"),s=t&&new URL(t.href).searchParams.get("v");if(!/^[\w-]{11}$/.test(s)||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();const o=document.activeElement===t,c=Object.assign(document.createElement("iframe"),{className:"stets-youtube",title:"YouTube video",src:`https://www.youtube-nocookie.com/embed/${s}?autoplay=1`,allow:"autoplay; encrypted-media; fullscreen; picture-in-picture",referrerPolicy:"strict-origin-when-cross-origin"});t.replaceWith(c),o&&c.focus()}),document.addEventListener("mousedown",e=>{e.button===0&&e.target.closest?.("a.stets-youtube")&&e.preventDefault()})})();
